def rc(x): return x.translate(str.maketrans('ACGT','TGCA'))[::-1]
stop={'TAA','TAG','TGA'}
def scan(ss, L, strand):
    for off in range(3):
        start=None
        i=off
        while i+2 < L:
            c=ss[i:i+3]
            if c=='ATG' and start is None:
                start=i
            if c in stop:
                if start is not None:
                    yield (i+3-start, start, i+3, strand)
                start=None
            i+=3
        if start is not None and start < L-150:  # long trailing ORF without stop? maybe ignore; but include if >150
            yield (L-start, start, L, strand)
